CREATE FUNCTION public.welfare_is_hr() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT hr_active_staff() AND (has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM hr_access WHERE user_id=auth.uid() AND access_role='hr')) $$;
CREATE FUNCTION public.welfare_is_management() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT hr_active_staff() AND (has_role(auth.uid(),'super_admin') OR EXISTS(SELECT 1 FROM profiles WHERE user_id=auth.uid() AND department='management')) $$;
CREATE TABLE public.welfare_policies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, eligibility text NOT NULL DEFAULT '', benefit_amount numeric(14,2), max_amount numeric(14,2), no_limit boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')), version integer NOT NULL DEFAULT 1, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(benefit_amount IS NULL OR benefit_amount>0), CHECK(max_amount IS NULL OR max_amount>0));
GRANT SELECT ON public.welfare_policies TO authenticated; GRANT ALL ON public.welfare_policies TO service_role;
ALTER TABLE public.welfare_policies ENABLE ROW LEVEL SECURITY;
CREATE POLICY welfare_policy_read ON public.welfare_policies FOR SELECT TO authenticated USING(hr_active_staff() AND (status='active' OR welfare_is_hr() OR welfare_is_management()));
CREATE TABLE public.welfare_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES public.hr_employees(id), requested_by uuid NOT NULL, policy_id uuid NOT NULL REFERENCES public.welfare_policies(id), policy_snapshot jsonb NOT NULL, amount numeric(14,2) NOT NULL CHECK(amount>0), reason text NOT NULL, status text NOT NULL DEFAULT 'hr_review' CHECK(status IN ('hr_review','management_review','approved','rejected','cancelled')), hr_reviewed_by uuid, hr_note text, hr_reviewed_at timestamptz, management_reviewed_by uuid, management_note text, management_reviewed_at timestamptz, voucher_id uuid UNIQUE REFERENCES public.vouchers(id), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.welfare_requests TO authenticated; GRANT ALL ON public.welfare_requests TO service_role;
ALTER TABLE public.welfare_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY welfare_request_read ON public.welfare_requests FOR SELECT TO authenticated USING(hr_active_staff() AND (requested_by=auth.uid() OR welfare_is_hr() OR welfare_is_management()));
CREATE INDEX welfare_request_employee_idx ON public.welfare_requests(employee_id,created_at);
CREATE TRIGGER welfare_policy_audit AFTER INSERT OR UPDATE ON public.welfare_policies FOR EACH ROW EXECUTE FUNCTION public.hr_audit_change();
CREATE TRIGGER welfare_request_audit AFTER INSERT OR UPDATE ON public.welfare_requests FOR EACH ROW EXECUTE FUNCTION public.hr_audit_change();
CREATE FUNCTION public.welfare_save_policy(_id uuid,_name text,_eligibility text,_benefit numeric,_max numeric,_no_limit boolean,_status text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; BEGIN
IF NOT (welfare_is_hr() OR welfare_is_management()) THEN RAISE EXCEPTION 'HR or management access required'; END IF;
IF _name IS NULL OR length(btrim(_name))<2 OR length(_name)>200 OR _eligibility IS NULL OR length(_eligibility)>4000 OR _status IS NULL OR _status NOT IN ('draft','active','archived') OR _no_limit IS NULL THEN RAISE EXCEPTION 'Enter a category name and valid policy details'; END IF;
IF (_benefit IS NOT NULL AND (_benefit<=0 OR _benefit<>round(_benefit,2))) OR (_max IS NOT NULL AND (_max<=0 OR _max<>round(_max,2))) OR (_no_limit AND _max IS NOT NULL) OR (_benefit IS NOT NULL AND _max IS NOT NULL AND _benefit>_max) THEN RAISE EXCEPTION 'Enter positive GHS amounts with at most two decimals; benefit must not exceed the limit'; END IF;
IF _status='active' AND (length(btrim(_eligibility))<3 OR (NOT _no_limit AND _max IS NULL)) THEN RAISE EXCEPTION 'Set eligibility and a request limit, or explicitly choose no limit, before activation'; END IF;
IF _id IS NULL THEN INSERT INTO welfare_policies(name,eligibility,benefit_amount,max_amount,no_limit,status,created_by) VALUES(btrim(_name),btrim(_eligibility),_benefit,_max,_no_limit,_status,auth.uid()) RETURNING id INTO r;
ELSE UPDATE welfare_policies SET name=btrim(_name),eligibility=btrim(_eligibility),benefit_amount=_benefit,max_amount=_max,no_limit=_no_limit,status=_status,version=version+1,updated_at=now() WHERE id=_id RETURNING id INTO r; IF r IS NULL THEN RAISE EXCEPTION 'Policy not found'; END IF; END IF; RETURN r; END $$;
CREATE FUNCTION public.welfare_submit(_policy uuid,_amount numeric,_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p welfare_policies; e uuid; r uuid; BEGIN
IF NOT hr_active_staff() THEN RAISE EXCEPTION 'An active unlocked staff account is required'; END IF;
SELECT id INTO e FROM hr_employees WHERE user_id=auth.uid() AND status IN ('active','probation') FOR UPDATE; IF e IS NULL THEN RAISE EXCEPTION 'An active linked employee record is required'; END IF;
SELECT * INTO p FROM welfare_policies WHERE id=_policy AND status='active' FOR SHARE; IF p.id IS NULL THEN RAISE EXCEPTION 'Select an active welfare category'; END IF;
IF _amount IS NULL OR _amount<=0 OR _amount>999999999999.99 OR _amount<>round(_amount,2) OR _reason IS NULL OR length(btrim(_reason))<3 OR length(_reason)>4000 THEN RAISE EXCEPTION 'Enter a positive GHS amount and reason (3 to 4000 characters)'; END IF;
IF (p.max_amount IS NOT NULL AND _amount>p.max_amount) OR (p.benefit_amount IS NOT NULL AND _amount<>p.benefit_amount) THEN RAISE EXCEPTION 'Requested amount does not meet this category policy'; END IF;
INSERT INTO welfare_requests(employee_id,requested_by,policy_id,policy_snapshot,amount,reason) VALUES(e,auth.uid(),p.id,jsonb_build_object('name',p.name,'eligibility',p.eligibility,'benefit_amount',p.benefit_amount,'max_amount',p.max_amount,'no_limit',p.no_limit,'version',p.version),_amount,btrim(_reason)) RETURNING id INTO r;
INSERT INTO notifications(title,message,recipient_id,reference_id,reference_type,action_url) SELECT 'Welfare review requested','A welfare request is awaiting HR review.',user_id,r::text,'welfare','/hr' FROM profiles WHERE is_active AND NOT is_locked AND user_id<>auth.uid() AND (has_role(user_id,'super_admin') OR EXISTS(SELECT 1 FROM hr_access a WHERE a.user_id=profiles.user_id AND a.access_role='hr')); RETURN r; END $$;
CREATE FUNCTION public.welfare_review(_id uuid,_stage text,_decision text,_note text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r welfare_requests; v uuid; n text; BEGIN
SELECT * INTO r FROM welfare_requests WHERE id=_id FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Request not found'; END IF;
IF NOT hr_active_staff() OR r.requested_by=auth.uid() THEN RAISE EXCEPTION 'You cannot review your own request; active reviewer access required'; END IF;
IF _decision IS NULL OR _decision NOT IN ('approve','reject') OR _note IS NULL OR length(btrim(_note))<3 OR length(_note)>4000 THEN RAISE EXCEPTION 'Choose a decision and enter a review note (3 to 4000 characters)'; END IF;
IF _stage='hr' THEN
IF NOT welfare_is_hr() OR r.status<>'hr_review' THEN RAISE EXCEPTION 'Only HR can review requests awaiting HR review'; END IF;
UPDATE welfare_requests SET status=CASE WHEN _decision='approve' THEN 'management_review' ELSE 'rejected' END,hr_reviewed_by=auth.uid(),hr_reviewed_at=now(),hr_note=btrim(_note) WHERE id=_id;
IF _decision='approve' THEN INSERT INTO notifications(title,message,recipient_id,reference_id,reference_type,action_url) SELECT 'Welfare approval requested','An HR-reviewed welfare request awaits management approval.',user_id,r.id::text,'welfare','/hr' FROM profiles WHERE is_active AND NOT is_locked AND user_id<>auth.uid() AND user_id<>r.requested_by AND (department='management' OR has_role(user_id,'super_admin')); END IF;
ELSIF _stage='management' THEN
IF NOT welfare_is_management() OR r.status<>'management_review' OR r.hr_reviewed_by IS NULL OR r.hr_reviewed_by=auth.uid() THEN RAISE EXCEPTION 'Management approval requires a different person after HR review'; END IF;
IF _decision='approve' THEN
SELECT full_name INTO n FROM hr_employees WHERE id=r.employee_id;
INSERT INTO vouchers(voucher_type,reference,narration,party_name,currency,exchange_rate,total_amount,ghs_equivalent,created_by) VALUES('payment','WELFARE:'||r.id::text,'Welfare payment '||r.id::text,n,'GHS',1,r.amount,r.amount,auth.uid()) RETURNING id INTO v;
INSERT INTO notifications(title,message,recipient_id,reference_id,reference_type,action_url) SELECT 'Welfare voucher ready','An approved welfare payment voucher awaits Accounts processing.',user_id,v::text,'voucher','/accounts/payment-vouchers' FROM profiles WHERE is_active AND NOT is_locked AND (department='accounts' OR has_role(user_id,'super_admin'));
END IF;
UPDATE welfare_requests SET status=CASE WHEN _decision='approve' THEN 'approved' ELSE 'rejected' END,management_reviewed_by=auth.uid(),management_reviewed_at=now(),management_note=btrim(_note),voucher_id=v WHERE id=_id;
ELSE RAISE EXCEPTION 'Invalid review stage'; END IF;
INSERT INTO notifications(title,message,recipient_id,reference_id,reference_type,action_url) VALUES('Welfare request updated','Your welfare request has been reviewed.',r.requested_by,r.id::text,'welfare','/hr'); RETURN v; END $$;
CREATE FUNCTION public.welfare_cancel(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NOT hr_active_staff() THEN RAISE EXCEPTION 'Active staff account required'; END IF;
UPDATE welfare_requests SET status='cancelled' WHERE id=_id AND requested_by=auth.uid() AND status='hr_review'; IF NOT FOUND THEN RAISE EXCEPTION 'Only your requests awaiting HR review can be cancelled'; END IF; END $$;
CREATE FUNCTION public.welfare_payment_status(_id uuid) RETURNS TABLE(voucher_no text,status text,posted_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.voucher_no,v.status,v.posted_at FROM welfare_requests r JOIN vouchers v ON v.id=r.voucher_id WHERE r.id=_id AND hr_active_staff() AND (r.requested_by=auth.uid() OR welfare_is_hr() OR welfare_is_management()) $$;
CREATE FUNCTION public.welfare_voucher_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r welfare_requests; d numeric; c numeric; BEGIN
SELECT * INTO r FROM welfare_requests WHERE voucher_id=NEW.id; IF r.id IS NULL THEN RETURN NEW; END IF;
IF NEW.voucher_type<>'payment' OR NEW.currency<>'GHS' OR NEW.exchange_rate<>1 OR NEW.reference IS DISTINCT FROM OLD.reference OR NEW.party_name IS DISTINCT FROM OLD.party_name OR NEW.consignment_id IS NOT NULL OR NEW.customer_id IS NOT NULL OR NEW.invoice_id IS NOT NULL THEN RAISE EXCEPTION 'Welfare voucher identity and currency cannot be changed'; END IF;
IF NEW.status='posted' AND OLD.status<>'posted' THEN
SELECT coalesce(sum(debit),0),coalesce(sum(credit),0) INTO d,c FROM voucher_lines WHERE voucher_id=NEW.id;
IF r.status<>'approved' OR d<>r.amount OR c<>r.amount OR NEW.total_amount<>r.amount OR NEW.ghs_equivalent<>r.amount THEN RAISE EXCEPTION 'Welfare voucher must match the management-approved amount'; END IF;
END IF; RETURN NEW; END $$;
CREATE TRIGGER welfare_voucher_guard BEFORE UPDATE ON public.vouchers FOR EACH ROW EXECUTE FUNCTION public.welfare_voucher_guard();
REVOKE ALL ON FUNCTION public.welfare_is_hr(),public.welfare_is_management(),public.welfare_save_policy(uuid,text,text,numeric,numeric,boolean,text),public.welfare_submit(uuid,numeric,text),public.welfare_review(uuid,text,text,text),public.welfare_cancel(uuid),public.welfare_payment_status(uuid),public.welfare_voucher_guard() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.welfare_is_hr(),public.welfare_is_management(),public.welfare_save_policy(uuid,text,text,numeric,numeric,boolean,text),public.welfare_submit(uuid,numeric,text),public.welfare_review(uuid,text,text,text),public.welfare_cancel(uuid),public.welfare_payment_status(uuid) TO authenticated;